int tipc_nl_dump(struct sk_buff *skb, struct netlink_callback *cb)
{
    struct tipc_port *port;
    int ret;

    if (cb->args[0])
        return skb->len;

    port = tipc_port_get(cb->args[1]);
    if (IS_ERR(port))
        return PTR_ERR(port);

    if (port->last_publ >= cb->args[2]) {
        cb->args[0] = 1;
        return skb->len;
    }

    ret = tipc_nl_fill(skb, port, cb->args[2], cb->nlh->nlmsg_seq, NLM_F_MULTI);
    if (ret < 0) {
        tipc_port_put(port);
        return ret;
    }

    cb->args[2]++;
    cb->args[3] = 1;
    tipc_port_put(port);

    return skb->len;
}

int tipc_dump_sk(struct sk_buff *skb, struct netlink_callback *cb)
{
    int pid = cb->args[0];
    int last_publ = cb->args[1];
    int done = cb->args[2];
    struct tipc_port *port;
    struct tipc_sock *ts;
    int res;

    if (!pid) {
        struct nlmsghdr *nlh = nlmsg_hdr(skb);
        if (!nlh)
            return -EINVAL;
        pid = nlh->nlmsg_pid;
    }

    if (done)
        return skb->len;

    rcu_read_lock();
    port = tipc_port_find(pid);
    if (!port) {
        rcu_read_unlock();
        return -ENOENT;
    }

    ts = container_of(port, struct tipc_sock, port);
    sock_lock(&ts->sk);

    if (last_publ < ts->publ_count) {
        res = tipc_sock_publish_info(skb, ts, last_publ);
        if (res < 0) {
            sock_unlock(&ts->sk);
            rcu_read_unlock();
            return res;
        }
        cb->args[1] = last_publ + 1;
    } else {
        cb->args[2] = 1;
    }

    sock_unlock(&ts->sk);
    rcu_read_unlock();
    return skb->len;
}

int tipc_netlink_dump(struct sk_buff *skb, struct netlink_callback *cb)
{
    int portid = cb->args[0];
    struct tipc_sock *tsk;
    int len = 0;
    int err;

    if (!portid) {
        portid = netlink_get_port(skb);
        if (portid < 0)
            return portid;
    }

    if (cb->args[1])
        return 0;

    tsk = tipc_sk_lookup(skb->sk, portid);
    if (!tsk)
        return -ENOENT;

    lock_sock(tsk);
    len = tipc_sk_dump_publ(skb, tsk, &cb->args[1]);
    if (len < 0) {
        err = len;
        release_sock(tsk);
        return err;
    }

    cb->args[0] = portid;
    release_sock(tsk);
    return skb->len;
}

int tipc_dump_sk(struct sk_buff *skb, struct netlink_callback *cb)
{
    int pid;
    struct tipc_socket *sock;
    int last_publ = 0;
    int done = 0;
    int len = 0;

    if (!cb->args[0]) {
        pid = nlmsg_parse(skb, cb->nlh, NULL, 0, NULL);
        if (pid < 0)
            return pid;
    } else {
        pid = cb->args[0];
    }

    if (cb->args[1])
        return skb->len;

    sock = tipc_socket_lookup(pid);
    if (!sock)
        return -ENOENT;

    mutex_lock(&sock->lock);

    while (!done && (last_publ < sock->publ_count)) {
        len += tipc_publ_dump(skb, &sock->publ_list[last_publ]);
        last_publ++;
        if (len >= skb->len)
            break;
    }

    cb->args[0] = pid;
    cb->args[1] = last_publ;
    if (done)
        cb->done = 1;

    mutex_unlock(&sock->lock);
    return len;
}

int tipc_netlink_dump(struct sk_buff *skb, struct netlink_callback *cb)
{
    int pid;
    struct tipc_port *port;
    struct tipc_sock *ts;
    int len = 0;

    if (!cb->args[0]) {
        pid = nlmsg_parse(cb->nlh, 0, NULL, 0, NULL);
        if (pid < 0)
            return pid;
    } else {
        pid = cb->args[0];
    }

    if (cb->args[1])
        return 0;

    port = tipc_port_find(pid);
    if (!port)
        return -ESRCH;

    ts = container_of(port, struct tipc_sock, port);
    spin_lock_bh(&ts->lock);

    len = skb->len;

    if (!cb->args[2])
        tipc_sk_publish_list(skb, ts, &cb->args[2]);

    cb->args[0] = pid;
    cb->args[1] = 1;
    spin_unlock_bh(&ts->lock);

    return len;
}
